CREATE TABLE annotations (id TEXT PRIMARY KEY, job_id TEXT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE audit_log (id INTEGER PRIMARY KEY AUTOINCREMENT, task_id TEXT NOT NULL, action TEXT NOT NULL, object_id TEXT NOT NULL, payload TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE claims (id TEXT PRIMARY KEY, status TEXT NOT NULL, payload TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE clarification_questions (id TEXT PRIMARY KEY, job_id TEXT NOT NULL, status TEXT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE completeness_assessments (id TEXT PRIMARY KEY, job_id TEXT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE conflicts (id TEXT PRIMARY KEY, payload TEXT NOT NULL);
CREATE TABLE entities (id TEXT PRIMARY KEY, payload TEXT NOT NULL);
CREATE TABLE entity_aliases (id TEXT PRIMARY KEY, canonical_surface TEXT NOT NULL, alias_surface TEXT NOT NULL, relation TEXT NOT NULL, passage_id TEXT NOT NULL, confidence REAL NOT NULL, payload TEXT NOT NULL);
CREATE TABLE events (id TEXT PRIMARY KEY, payload TEXT NOT NULL);
CREATE TABLE evidence (id TEXT PRIMARY KEY, claim_id TEXT NOT NULL, passage_id TEXT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE evolution_snapshots (id TEXT PRIMARY KEY, policy_version TEXT NOT NULL, payload TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE extraction_batches (id TEXT PRIMARY KEY, status TEXT NOT NULL, passage_ids TEXT NOT NULL, attempt INTEGER NOT NULL DEFAULT 0, error TEXT, payload TEXT NOT NULL);
CREATE TABLE extraction_passages (passage_id TEXT PRIMARY KEY, status TEXT NOT NULL, batch_id TEXT NOT NULL, error TEXT);
CREATE TABLE ingestion_artifacts (id TEXT PRIMARY KEY, job_id TEXT NOT NULL, kind TEXT NOT NULL, input_hash TEXT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE ingestion_jobs (id TEXT PRIMARY KEY, status TEXT NOT NULL, payload TEXT NOT NULL, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE normalized_documents (id TEXT PRIMARY KEY, job_id TEXT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE passages (id TEXT PRIMARY KEY, source_id TEXT NOT NULL, ordinal INTEGER NOT NULL, payload TEXT NOT NULL);
CREATE TABLE people_extraction_batches (id TEXT PRIMARY KEY, status TEXT NOT NULL, passage_ids TEXT NOT NULL, attempt INTEGER NOT NULL DEFAULT 0, error TEXT, payload TEXT NOT NULL);
CREATE TABLE people_extraction_passages (passage_id TEXT PRIMARY KEY, status TEXT NOT NULL, batch_id TEXT NOT NULL, error TEXT);
CREATE TABLE place_assertions (id TEXT PRIMARY KEY, event_id TEXT NOT NULL, place TEXT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE processing_errors (id TEXT PRIMARY KEY, job_id TEXT NOT NULL, stage TEXT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE raw_assets (id TEXT PRIMARY KEY, content_hash TEXT NOT NULL UNIQUE, payload TEXT NOT NULL);
CREATE TABLE recognition_results (id TEXT PRIMARY KEY, job_id TEXT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE relations (id TEXT PRIMARY KEY, subject TEXT NOT NULL, predicate TEXT NOT NULL, object TEXT NOT NULL, payload TEXT NOT NULL, claim_id TEXT, valid_from TEXT, valid_to TEXT, inference_method TEXT NOT NULL DEFAULT 'explicit', confidence REAL);
CREATE TABLE review_feedback (id TEXT PRIMARY KEY, claim_id TEXT NOT NULL, label TEXT NOT NULL, reason TEXT NOT NULL, reviewer TEXT NOT NULL, payload TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE review_tasks (id TEXT PRIMARY KEY, job_id TEXT NOT NULL, status TEXT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE sources (id TEXT PRIMARY KEY, payload TEXT NOT NULL);
CREATE TABLE timeline_entries (id TEXT PRIMARY KEY, event_id TEXT NOT NULL, start_date TEXT, end_date TEXT, payload TEXT NOT NULL);
CREATE INDEX idx_claims_object ON claims(json_extract(payload, '$.object'));
CREATE INDEX idx_claims_status ON claims(status);
CREATE INDEX idx_claims_subject_predicate ON claims(json_extract(payload, '$.subject'), json_extract(payload, '$.predicate'));
CREATE INDEX idx_entities_surface ON entities(json_extract(payload, '$.surface'));
CREATE INDEX idx_entities_type ON entities(json_extract(payload, '$.entity_type'));
CREATE INDEX idx_entity_aliases_alias ON entity_aliases(alias_surface);
CREATE INDEX idx_events_dates ON events(json_extract(payload, '$.date_start'), json_extract(payload, '$.date_end'));
CREATE INDEX idx_events_place ON events(json_extract(payload, '$.place'));
CREATE INDEX idx_evidence_claim ON evidence(claim_id);
CREATE INDEX idx_evidence_passage ON evidence(passage_id);
CREATE INDEX idx_passages_source ON passages(source_id);
CREATE INDEX idx_places_place ON place_assertions(place);
CREATE INDEX idx_relations_claim ON relations(claim_id);
CREATE INDEX idx_relations_object ON relations(object);
CREATE INDEX idx_relations_subject_predicate ON relations(subject, predicate);
CREATE INDEX idx_relations_valid_time ON relations(valid_from, valid_to);
CREATE INDEX idx_timeline_dates ON timeline_entries(start_date, end_date);
